#pragma once
#include "flitzfs/gpu_batch.hpp"
#include "flitzfs/gpu_match.hpp"

namespace flitzfs {
class PreparedLz4WorkerBatch;

// Identity of an externally qualified adapter/runtime/module/helper/backend combination, not
// a version counter generated by the retry loop. All-zero means unqualified.
using GpuConfigurationId = std::array<std::byte,32>;

struct GpuHealthEvidence {
  GpuConfigurationId configuration{};
  std::uint64_t sequence = 0;
  // Increased only by separately successful device/driver recovery qualification.
  // Fresh memory telemetry alone is NOT recovery qualification.
  std::uint64_t recovery_generation = 0;
  bool compatible = false;
  bool supervisor_quiescent = false;
  GpuMemorySnapshot memory;
};

enum class GpuRecoveryOutcome {
  accepted, temporary_pressure, runtime_unavailable, unsupported_configuration,
  device_fault, integrity_failure
};
enum class GpuRouteReason {
  candidate, disabled, unqualified, worker_busy, bad_evidence, memory_pressure,
  recovering, configuration_blocked, device_quarantined, exhausted
};
struct GpuRouteDecision {
  GpuRouteReason reason = GpuRouteReason::unqualified;
  std::uint64_t ticket = 0;
  bool try_gpu() const noexcept { return reason == GpuRouteReason::candidate; }
};

// Single control thread. Constant memory/work, no OS/runtime calls, waits,
// discovery or allocation. Consumes externally supplied qualified evidence.
// An admitted candidate still needs a terminal result gate and worker limits.
// CPU work never depends on this policy granting another attempt.
class GpuRecoveryPolicy final {
 public:
  GpuRecoveryPolicy() = default;
  GpuRecoveryPolicy(const GpuRecoveryPolicy&) = delete;
  GpuRecoveryPolicy& operator=(const GpuRecoveryPolicy&) = delete;
  GpuRecoveryPolicy(GpuRecoveryPolicy&&) = delete;
  GpuRecoveryPolicy& operator=(GpuRecoveryPolicy&&) = delete;
  GpuRouteDecision consider(bool explicit_consent, bool workload_qualified,
      const GpuHealthEvidence& evidence, const PreparedGpuBatch& batch,
      std::uint64_t now_ms) noexcept;
  GpuRouteDecision consider(bool explicit_consent,bool workload_qualified,
      const GpuHealthEvidence& evidence,const PreparedGpuMatchSearch& search,
      std::uint64_t now_ms) noexcept;
  GpuRouteDecision consider(bool explicit_consent,bool workload_qualified,
      const GpuHealthEvidence&,const PreparedLz4WorkerBatch&,std::uint64_t now_ms) noexcept;
  // Report once. A failure can be recorded before teardown; an unconfirmed
  // worker continues to block EVERY new GPU attempt, including changed configs.
  bool finish(std::uint64_t ticket, GpuRecoveryOutcome outcome,
      bool supervisor_confirmed_quiescent) noexcept;
  // Separate supervisor confirmation after a previously reported outcome.
  bool confirm_quiescent(std::uint64_t ticket) noexcept;
  unsigned consecutive_failures() const noexcept { return failures_; }
  unsigned required_healthy_observations() const noexcept;

 private:
  GpuRouteDecision consider_work(bool,bool,const GpuHealthEvidence&,
      bool has_work,std::uint64_t device_bytes,std::uint64_t now_ms) noexcept;
  GpuConfigurationId configuration_{};
  std::array<std::byte,8> luid_{};
  std::uint32_t node_mask_ = 0;
  std::uint64_t last_sequence_ = 0, last_capture_ = 0, last_now_ = 0;
  std::uint64_t recovery_floor_ = 0, observed_recovery_ = 0;
  std::uint64_t active_ticket_ = 0, next_ticket_ = 1;
  unsigned failures_ = 0, healthy_ = 0, successes_ = 0;
  GpuRecoveryOutcome last_outcome_ = GpuRecoveryOutcome::accepted;
  bool reported_ = false, clock_seen_ = false;
  struct Quarantine {
    GpuConfigurationId configuration{};
    std::uint64_t recovery_floor = 0;
    bool hard = false;
  };
  // Switching A->B->A must not forget a known bad configuration. Exhaustion
  // disables further GPU candidates rather than evicting safety history.
  std::array<Quarantine,8> quarantines_{};
  bool quarantine_full_ = false;
};
} // namespace flitzfs
